    resource("worker", { labels: { bRaNcH: "feat-a", Team: "payments" }, depends_on: ["network", "boot"] }),
    resource("cdk-volume", { type: "volume", labels: { BRANCH: "feat-a" } }),
    resource("other-worker", { labels: { Branch: "feat-b" } }),
    resource("case-sensitive", { labels: { Branch: "FEAT-A" } }),
    resource("tag-wins", { tags: { branch: "feat-b" }, labels: { Branch: "feat-a" }, stack_id: "stk-feat-a" }),
    resource("orphan"),
  ];
  if (externalBlocker) resources.push(resource("external", { labels: { Branch: "feat-b" }, depends_on: ["network"] }));
  const deleted: string[] = [];
  const cursors: string[] = [];
  const server = createServer((req, res) => {
    res.setHeader("content-type", "application/json");
    const url = new URL(req.url!, "http://localhost");
    if (req.headers.authorization !== "Bearer test-token") {
      res.writeHead(401).end(JSON.stringify({ error: "bad token" }));
    } else if (req.method === "GET" && url.pathname === "/v1/resources") {
      const cursor = url.searchParams.get("cursor")!;
      cursors.push(cursor);
      const start = cursor === "0" ? 0 : 20;
      const page = resources.slice(start, start + 20);
      res.end(JSON.stringify({ resources: page, next_cursor: start === 0 ? "later/page" : null }));
    } else if (req.method === "DELETE" && url.pathname.startsWith("/v1/resources/")) {
      const id = decodeURIComponent(url.pathname.slice("/v1/resources/".length));
      const dependents = resources.filter(r => (r.depends_on as string[]).includes(id));
      if (dependents.length) {
        res.writeHead(409).end(JSON.stringify({ error: "resource has dependents", dependents: dependents.map(r => r.id) }));
        return;
      }
      const index = resources.findIndex(r => r.id === id);
      if (index < 0) {
        res.writeHead(404).end(JSON.stringify({ error: "not found" }));
        return;
      }
      resources.splice(index, 1);
      deleted.push(id);
      res.end(JSON.stringify({ deleted: id }));
    } else {
      res.writeHead(404).end(JSON.stringify({ error: "not found" }));
    }
  });
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  const address = server.address() as { port: number };
  return {
    resources, deleted, cursors,
    close: () => new Promise<void>((resolve, reject) => server.close(err => err ? reject(err) : resolve())),
    run: async (...args: string[]) => {
      const child = spawn(process.execPath, ["--experimental-strip-types", "--no-warnings", "src/cli.ts", ...args], {
        env: { ...process.env, ENVCTL_API: `http://127.0.0.1:${address.port}`, ENVCTL_TOKEN: "test-token" },
      });
      let stdout = "", stderr = "";
      child.stdout.on("data", data => { stdout += data; });
      child.stderr.on("data", data => { stderr += data; });
      const [code] = await once(child, "close");
      return { code, stdout, stderr };
    },
  };
}

test("CLI recognizes labels across pages for plan, list, gc and teardown", async () => {
  const api = await fixture();
  try {
    const planned = await api.run("plan", "--branch", "feat-a", "--json");
    assert.equal(planned.code, 0, planned.stderr);
    const plan = JSON.parse(planned.stdout);
    const ids = plan.steps.map((step: { id: string }) => step.id);
    assert.deepEqual([...ids].sort(), ["boot", "cdk-volume", "network", "worker"]);
    assert.deepEqual(plan.blocked, []);
    assert.ok(ids.indexOf("worker") < ids.indexOf("network"));
    assert.ok(ids.indexOf("worker") < ids.indexOf("boot"));
    assert.deepEqual(api.cursors, ["0", "later/page"]);

    const listing = await api.run("list");
    assert.equal(listing.code, 0, listing.stderr);
    assert.match(listing.stdout, /feat-a\s+3\s/);
    assert.match(listing.stdout, /2 untagged resources/); // stack-only boot volume and true orphan
    const gc = await api.run("gc", "--untagged");
    assert.equal(gc.code, 0, gc.stderr);
    assert.match(gc.stdout, /^2 untagged resources/);
    assert.deepEqual(api.deleted, []);

    const dryRun = await api.run("teardown", "--branch", "feat-a", "--dry-run");
    assert.equal(dryRun.code, 0, dryRun.stderr);
    assert.deepEqual(api.deleted, []);
    const teardown = await api.run("teardown", "--branch", "feat-a");
    assert.equal(teardown.code, 0, teardown.stderr);
    assert.deepEqual(api.deleted, ids);
    assert.ok(api.resources.some(r => r.id === "other-worker"));
    assert.ok(api.resources.some(r => r.id === "tag-wins"));
    assert.ok(api.resources.some(r => r.id === "case-sensitive"));
    assert.ok(api.resources.some(r => r.id === "orphan"));
  } finally {
    await api.close();
  }
});

test("CLI still refuses teardown for a genuinely external labeled dependent", async () => {
  const api = await fixture(true);
  try {
    const result = await api.run("plan", "--branch", "feat-a", "--json");
    assert.equal(result.code, 0, result.stderr);
    assert.deepEqual(JSON.parse(result.stdout).blocked, [{ id: "network", dependents: ["external"] }]);
    const teardown = await api.run("teardown", "--branch", "feat-a");
    assert.equal(teardown.code, 1);
    assert.match(teardown.stderr, /refusing to tear down/);
    assert.deepEqual(api.deleted, []);
  } finally {
    await api.close();
  }
});
